PRICES = {"book": 5000, "pen": 500, "bag": 15000}

def subtotal(lines):
    total = 0
    for sku, qty in lines:
        if sku not in PRICES or not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("invalid line")
        total += PRICES[sku] * qty
    return total

