class PaymentDeclined(Exception):
    pass

class Ledger:
    def __init__(self):
        self.charges = {}
        self.charge_count = 0
        self.decline_next = False

    def charge(self, request_id, amount):
        if request_id in self.charges:
            return self.charges[request_id]
        if self.decline_next:
            self.decline_next = False
            raise PaymentDeclined("declined")
        self.charges[request_id] = amount
        self.charge_count += 1
        return amount

