from .pricing import calculate_total
from .receipts import Receipt

class Checkout:
    def __init__(self, inventory, ledger):
        self.inventory = inventory
        self.ledger = ledger
        self.receipts = {}

    def place_order(self, request_id, lines):
        if request_id in self.receipts:
            return self.receipts[request_id]
        if not lines:
            raise ValueError("empty order")
        amount = calculate_total(lines)
        self.inventory.reserve(lines)
        paid = self.ledger.charge(request_id, amount)
        receipt = Receipt(request_id, paid)
        self.receipts[request_id] = receipt
        return receipt
